#!/usr/bin/env node
/**
 * Model Selection Utility
 * 
 * Reads Anti-Gravity model status and selects the best candidate.
 * Falls back to the fallback model if all candidates are below threshold.
 * Safe to run from cron.
 * 
 * Usage:
 *   node model-select.js [--status-json <file>] [--status-text <file>]
 *   node model-select.js --dry-run  # Only output decision, no action
 */

import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Configuration
const THRESHOLD = 20; // 20% - models below this are considered depleted
const FALLBACK_MODEL = 'google/gemini-3-flash-preview';
const AG_PREFIX = 'google-antigravity/';

// Allowed Anti-Gravity model candidates
const CANDIDATES = [
  'google-antigravity/claude-opus-4-5-thinking',
  'google-antigravity/claude-sonnet-4-5',
  'google-antigravity/claude-sonnet-4-5-thinking',
  'google-antigravity/gemini-3-flash',
  'google-antigravity/gemini-3-pro-high',
  'google-antigravity/gemini-3-pro-low',
  'google-antigravity/gpt-oss-120b-medium'
];

function parseArgs() {
  const args = process.argv.slice(2);
  const options = {
    statusJson: null,
    statusText: null,
    dryRun: false
  };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--status-json':
        options.statusJson = args[++i];
        break;
      case '--status-text':
        options.statusText = args[++i];
        break;
      case '--dry-run':
        options.dryRun = true;
        break;
      case '-h':
      case '--help':
        console.log(`Usage: node model-select.js [options]

Options:
  --status-json <file>  Path to status JSON file (default: ./status.json)
  --status-text <file>  Path to status text file (default: ./status.txt)
  --dry-run             Only output decision, do not execute model switch
  -h, --help            Show this help message

Example:
  node model-select.js --dry-run
  node model-select.js --status-json /path/to/status.json`);
        process.exit(0);
    }
  }

  return options;
}

function readFile(path) {
  try {
    return readFileSync(path, 'utf8').trim();
  } catch (e) {
    return null;
  }
}

function parseStatusJson(content) {
  if (!content) return null;
  try {
    const data = JSON.parse(content);
    return data.defaults?.model?.primary || '';
  } catch (e) {
    return null;
  }
}

function parseStatusText(content) {
  if (!content) return {};

  const usageMap = {};
  const lines = content.split('\n');

  // Default Gemini models to 100% (infinite quota)
  for (const cand of CANDIDATES) {
    if (cand.includes('gemini')) {
      usageMap[cand] = 100;
    }
  }

  for (const line of lines) {
    // Parse lines like "claude-sonnet-4-5 41% left"
    const regex = /([a-zA-Z0-9-.]+)\s+(\d+)%\s+left/g;
    let match;
    while ((match = regex.exec(line)) !== null) {
      let modelName = match[1];
      const percent = parseInt(match[2], 10);

      // Add prefix if missing
      if (!modelName.startsWith(AG_PREFIX)) {
        modelName = AG_PREFIX + modelName;
      }
      usageMap[modelName] = percent;
    }
  }

  return usageMap;
}

