    console.log(`[ModelSelect] ${decision.action.toUpperCase()}: ${decision.model}`);
    console.log(`[ModelSelect] Reason: ${decision.reason}`);
    console.log(`[ModelSelect] Current: ${currentModel || '(none)'}`);
    console.log(`[ModelSelect] Selected: ${decision.model} (${decision.percent}%)`);

